<?php require_once __DIR__.'/../includes/leave.php';require_login();$r=$_SESSION['role'];
$SA=['present'=>'حاضر','late'=>'متأخر','absent'=>'غائب','half_day'=>'نصف يوم','on_leave'=>'في إجازة','holiday'=>'عطلة رسمية','weekend'=>'عطلة أسبوعية'];
$m=preg_match('/^\d{4}-\d{2}$/',$_GET['m']??'')?$_GET['m']:date('Y-m');$first=strtotime("$m-01");$emp=(int)$_SESSION['eid'];
if($r!=='employee'&&!empty($_GET['emp'])){$c=$pdo->prepare('SELECT manager_id FROM employees WHERE id=?');$c->execute([(int)$_GET['emp']]);$mg=$c->fetch();
 if($mg&&($r==='admin'||(int)$mg['manager_id']===$emp||(int)$_GET['emp']===$emp))$emp=(int)$_GET['emp'];else{error_page(403,'غير مصرح لك بعرض هذا التقويم','يمكنك عرض تقويمك، وللمديرين تقويم فريقهم فقط.');}}
$s=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? AND work_date BETWEEN ? AND ?');$s->execute([$emp,"$m-01",date('Y-m-t',$first)]);$A=[];foreach($s as $x)$A[$x['work_date']]=$x;
$HOL=holiday_dates("$m-01",date('Y-m-t',$first));$WK=array_map('intval',array_filter(explode(',',(string)setting('weekend_days')),'strlen'));
$lq=$pdo->prepare("SELECT start_date,end_date FROM leave_requests WHERE employee_id=? AND status='approved' AND start_date<=? AND end_date>=?");$lq->execute([$emp,date('Y-m-t',$first),"$m-01"]);$LV=$lq->fetchAll();
$inLv=function($k)use($LV){foreach($LV as $x)if($x['start_date']<=$k&&$x['end_date']>=$k)return true;return false;};
$list=$r==='employee'?[]:$pdo->query($r==='admin'?'SELECT id,full_name FROM employees ORDER BY full_name':'SELECT id,full_name FROM employees WHERE manager_id='.(int)$_SESSION['eid'].' OR id='.(int)$_SESSION['eid'])->fetchAll();
page_start('تقويم الحضور');$pad=(int)date('w',$first);$en=$pdo->prepare('SELECT full_name FROM employees WHERE id=?');$en->execute([$emp]);$enm=$en->fetchColumn();$pm=date('Y-m',strtotime('-1 month',$first));$nm=date('Y-m',strtotime('+1 month',$first));$q=$list?'&emp='.$emp:'';
ph('تقويم الحضور',$enm?'حالة الحضور اليومية لـ '.$enm:'');?>
<form class="card filters" method="get"><label>الشهر<input type="month" name="m" value="<?=e($m)?>"></label><?php if($list):?><label>الموظف<select name="emp"><?php foreach($list as $x)echo '<option value="'.$x['id'].'" '.($emp==$x['id']?'selected':'').'>'.e($x['full_name']).'</option>';?></select></label><?php endif;?><button class="btn">عرض</button></form>
<div class="card"><div class="cal-head"><h3><?=e(ar_month($m))?></h3><div class="row noprint"><a class="btn ghost sm" href="?m=<?=$pm.$q?>"><?=ic('chev-right')?>السابق</a><a class="btn ghost sm" href="?m=<?=date('Y-m').$q?>">هذا الشهر</a><a class="btn ghost sm" href="?m=<?=$nm.$q?>">التالي<?=ic('chev-left')?></a></div></div>
<div class="cal"><?php foreach(['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'] as $d)echo '<div class="h">'.$d.'</div>';for($i=0;$i<$pad;$i++)echo '<div class="pad"></div>';
for($d=1;$d<=(int)date('t',$first);$d++){$k=sprintf('%s-%02d',$m,$d);$a=$A[$k]??null;$s0=in_array($k,$HOL,true)?'holiday':(in_array((int)date('w',strtotime($k)),$WK,true)?'weekend':($inLv($k)?'on_leave':null));if($s0)$a=array_merge($a?:['check_in'=>null,'check_out'=>null,'late_minutes'=>null,'early_leave_minutes'=>null,'overtime_minutes'=>null],['status'=>$s0]);
 echo '<div class="day '.($a['status']??'none').($k===date('Y-m-d')?' is-today':'').'" role="button" tabindex="0" aria-label="'.e($d.' — '.($a?$SA[$a['status']]:'لا يوجد سجل')).'" onclick="dayOpen(this)" data-j="'.e(json_encode(['د'=>$k,'ح'=>$a?$SA[$a['status']]:'لا يوجد سجل','دخول'=>$a['check_in']??'—','خروج'=>$a['check_out']??'—','تأخير (د)'=>$a['late_minutes']??'—','خروج مبكر (د)'=>$a['early_leave_minutes']??'—','إضافي (د)'=>$a['overtime_minutes']??'—'],JSON_UNESCAPED_UNICODE)).'"><b>'.$d.'</b>'.($a?'<small>'.$SA[$a['status']].'</small>':'').'</div>';}?></div>
<div class="legend"><span class="lg-i"><i class="present"></i>حاضر</span><span class="lg-i"><i class="late"></i>متأخر</span><span class="lg-i"><i class="half_day"></i>نصف يوم</span><span class="lg-i"><i class="absent"></i>غائب</span><span class="lg-i"><i class="on_leave"></i>إجازة</span><span class="lg-i"><i class="holiday"></i>عطلة / نهاية أسبوع</span></div></div>
<?php modal_open('dm',(string)$enm,['desc'=>'تفاصيل اليوم']);?><div class="kv" id="dtb"></div><?php modal_close('<button type="button" class="btn ghost" data-close>إغلاق</button>');?>
<script>function dayOpen(el){const j=JSON.parse(el.dataset.j);document.getElementById("dtb").innerHTML=Object.entries({"التاريخ":j["د"],"الحالة":j["ح"],"وقت الدخول":j["دخول"],"وقت الخروج":j["خروج"],"التأخير (د)":j["تأخير (د)"],"الخروج المبكر (د)":j["خروج مبكر (د)"],"العمل الإضافي (د)":j["إضافي (د)"]}).map(([k,v])=>"<div><span>"+k+"</span><b>"+v+"</b></div>").join("");openModal("dm");}
document.querySelectorAll(".day").forEach(d=>d.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();dayOpen(d);}}));</script><?php page_end();
